import fs from 'fs';
import path from 'path';
import {
  isStaticHtmlFilePath,
  resolveStaticProjectTarget,
} from '../services/staticProjectTarget';
import {
  isPathStrictlyInsideRoot,
  resolveRealPathWithinRoot,
} from '../utils/pathContainment';
import { createLogger } from '../utils/logger';
import type { WorktreeRecord } from './WorkspaceInventory';
import type {
  ProjectEnvironment,
  WorktreeManagerLike,
} from './variant-project-runtime';
import {
  trackPreviewStarted,
  type VariantsTelemetry,
} from './variantsTelemetry';

const log = createLogger('ExistingStaticEntry');

const INDEX_PAGE = 'index.html';

export type ExistingStaticEntrySource =
  'configured' | 'root_page' | 'changed_page';

export type ExistingStaticEntry =
  | { kind: 'found'; entryPath: string; source: ExistingStaticEntrySource }
  | { kind: 'missing'; detail: string; source: 'configured' | 'none' };

export type ExistingStaticPreviewEntry =
  | { kind: 'unresolved' }
  | (ExistingStaticEntry & {
      hostProjectPath: string;
      projectDirectory: string;
      startedAt: number;
    });

const MISSING_PAGE_DETAIL =
  "This project has no index.html or package.json at its root, and this direction didn't add or change an HTML page. " +
  "Run rivet open on the folder that contains your app's package.json or index.html, or pass --entry <page.html>.";

const missingConfiguredEntryDetail = (entryPath: string): string =>
  `${entryPath} isn't in this direction's copy of the project. Directions start from committed and untracked files; ` +
  `git-ignored files are left out. Commit ${entryPath} or remove it from .gitignore, then generate the direction again.`;

const isPageInsideWorktree = async (
  worktreePath: string,
  pagePath: string,
): Promise<boolean> => {
  const realPage = await resolveRealPathWithinRoot({
    root: worktreePath,
    candidate: pagePath,
    containment: 'strict',
  });
  if (!realPage) return false;
  try {
    await fs.promises.access(realPage, fs.constants.R_OK);
    return (await fs.promises.stat(realPage)).isFile();
  } catch {
    return false;
  }
};

const pageDepth = (pagePath: string): number => pagePath.split('/').length;

const isIndexPage = (pagePath: string): boolean =>
  path.posix.basename(pagePath).toLowerCase() === INDEX_PAGE;

const comparePreviewPages = (left: string, right: string): number =>
  pageDepth(left) - pageDepth(right) ||
  Number(isIndexPage(right)) - Number(isIndexPage(left)) ||
  left.localeCompare(right);

const findRootPage = (projectDirectory: string): string | undefined => {
  try {
    return resolveStaticProjectTarget({ targetPath: projectDirectory })
      .entryPath;
  } catch {
    return undefined;
  }
};

const toProjectPagePaths = (args: {
  worktreePath: string;
  projectDirectory: string;
  changedFiles: string[];
}): string[] =>
  args.changedFiles
    .map((changedFile) => path.join(args.worktreePath, changedFile))
    .filter(
      (changedPath) =>
        isPathStrictlyInsideRoot(args.projectDirectory, changedPath) &&
        isStaticHtmlFilePath(changedPath),
    )
    .map((changedPath) =>
      path
        .relative(args.projectDirectory, changedPath)
        .split(path.sep)
        .join('/'),
    )
    .sort(comparePreviewPages);

export const resolveExistingStaticEntry = async (args: {
  worktreePath: string;
  projectDirectory: string;
  configuredEntryPath: string | undefined;
  changedFiles: string[];
}): Promise<ExistingStaticEntry> => {
  const isProjectPage = (entryPath: string) =>
    isPageInsideWorktree(
      args.worktreePath,
      path.join(args.projectDirectory, entryPath),
    );

  if (args.configuredEntryPath) {
    return (await isProjectPage(args.configuredEntryPath))
      ? {
          kind: 'found',
          entryPath: args.configuredEntryPath,
          source: 'configured',
        }
      : {
          kind: 'missing',
          detail: missingConfiguredEntryDetail(args.configuredEntryPath),
          source: 'configured',
        };
  }

  const rootPage = findRootPage(args.projectDirectory);
  if (rootPage && (await isProjectPage(rootPage))) {
    return { kind: 'found', entryPath: rootPage, source: 'root_page' };
  }

  for (const changedPage of toProjectPagePaths(args)) {
    if (await isProjectPage(changedPage)) {
      return { kind: 'found', entryPath: changedPage, source: 'changed_page' };
    }
  }

  return { kind: 'missing', detail: MISSING_PAGE_DETAIL, source: 'none' };
};

export const resolveExistingStaticPreviewEntry = async (args: {
  sessionId: string;
  record: WorktreeRecord;
  resolveEnv: (sessionId: string) => Promise<ProjectEnvironment>;
  worktrees: WorktreeManagerLike;
  telemetry: VariantsTelemetry;
}): Promise<ExistingStaticPreviewEntry | undefined> => {
  const { sessionId, record } = args;
  let env: ProjectEnvironment;
  try {
    env = await args.resolveEnv(sessionId);
  } catch (err) {
    log.warn(`resolveEnv failed for ${sessionId}`, err);
    return undefined;
  }
  if (env.framework !== 'static') return undefined;
  const startedAt = Date.now();
  trackPreviewStarted(args.telemetry, {
    sessionId,
    variantId: record.workItemId,
    projectContextKind: 'existing',
    previewKind: 'static_artifact',
  });

  let projectDirectory: string;
  try {
    projectDirectory = await args.worktrees.getProjectCwdInWorktree(
      record.worktreePath,
    );
  } catch (err) {
    log.warn(`project cwd failed for ${sessionId}/${record.workItemId}`, err);
    return { kind: 'unresolved' };
  }

  let changedFiles: string[] = [];
  if (!env.entryPath) {
    try {
      changedFiles =
        (await args.worktrees.getChangedFiles?.(record.worktreePath)) ?? [];
    } catch (err) {
      log.warn(
        `changed files unavailable for ${sessionId}/${record.workItemId}`,
        err,
      );
    }
  }
  const entry = await resolveExistingStaticEntry({
    worktreePath: record.worktreePath,
    projectDirectory,
    configuredEntryPath: env.entryPath,
    changedFiles,
  });
  return {
    ...entry,
    hostProjectPath: env.projectPath,
    projectDirectory,
    startedAt,
  };
};
